import{_ as t,o as s,c as o,a3 as a}from"./chunks/framework.Ch_0qWu9.js";const k=JSON.parse('{"title":"Solver protocols","description":"","frontmatter":{"sourcePath":"docs/solver-protocols.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/docs/solver-protocols.md","alternateUrl":"/TCSExam/docs/zh/solver-protocols/","alternateAnchors":{"solver-protocols":"solver-protocols","feedback-and-defaults":"feedback-and-defaults","select-and-prepare-a-protocol":"select-and-prepare-a-protocol","report-the-selected-protocol":"report-the-selected-protocol"}},"headers":[],"relativePath":"solver-protocols/index.md","filePath":"solver-protocols/index.md"}'),i={name:"solver-protocols/index.md"};function r(n,e,l,d,c,p){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="solver-protocols" tabindex="-1">Solver protocols <a class="header-anchor" href="#solver-protocols" aria-label="Permalink to &quot;Solver protocols&quot;">​</a></h1><p>This guide defines Solver feedback during development and protocol selection. It is for users choosing an evaluation protocol or preparing its dependencies.</p><h2 id="feedback-and-defaults" tabindex="-1">Feedback and defaults <a class="header-anchor" href="#feedback-and-defaults" aria-label="Permalink to &quot;Feedback and defaults&quot;">​</a></h2><p>Full contains 100 tasks; Lite selects 20 from across Full&#39;s task categories. In either suite, <code>--solver-protocol online|offline</code> chooses the Solver development-feedback protocol. Theorem, construction and open-conjecture tasks share the same folders under both choices. Full defaults to <code>online</code>; Lite defaults to <code>offline</code>. Either suite accepts an explicit override.</p><p>Read each row as one complete development and final-judging protocol.</p><table tabindex="0"><thead><tr><th>Protocol</th><th>During the twelve-hour development period</th><th>After development</th></tr></thead><tbody><tr><td><code>online</code></td><td><code>submit.sh</code> can request judging and return feedback</td><td>Judge the final submission on hidden instances</td></tr><tr><td><code>offline</code></td><td>Run local self-tests on public instances</td><td>Judge the final submission on hidden instances</td></tr></tbody></table><p>Offline provides no hidden-judge feedback during development. Both protocols use the same final task checker and scoring rules.</p><p>Internet access is a separate task setting: follow the task configuration and instructions for allowed network use.</p><h2 id="select-and-prepare-a-protocol" tabindex="-1">Select and prepare a protocol <a class="header-anchor" href="#select-and-prepare-a-protocol" aria-label="Permalink to &quot;Select and prepare a protocol&quot;">​</a></h2><p>All thirty Solver tasks have online and offline packages. The <a href="https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/suites/tasks.json" target="_blank" rel="noreferrer">task registry</a> maps tasks to their existing Harbor directories. Suite selection and protocol selection resolve these directories without changing task content.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lite</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tcsexam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --suite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> full</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --track</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> solver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --solver-protocol</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> online</span></span></code></pre></div><p>Prepare the selected images with <a href="/TCSExam/docs/resources/"><code>tcsexam build</code></a>, then run <code>tcsexam doctor</code> with the same selection. Missing dependencies stop <code>run</code> before any model request; a missing variant is an error.</p><p>Online additionally requires a user-operated judging backend. The packages supply clients and judging code; the <a href="/TCSExam/docs/solver-backend/">TCSEXAM interface</a> defines authentication, sessions, attempt identity and result archives.</p><p>Offline uses a separate judging adapter after development. It selects parallelism from available CPU and memory, with a serial fallback, while preserving per-instance limits. Shared-time-pool tasks remain in one pool. The model environment is isolated from hidden data and the Docker controller. See <a href="/TCSExam/docs/offline-adapters/">offline adapters</a> for adapter behavior.</p><h2 id="report-the-selected-protocol" tabindex="-1">Report the selected protocol <a class="header-anchor" href="#report-the-selected-protocol" aria-label="Permalink to &quot;Report the selected protocol&quot;">​</a></h2><p>Keep online and offline results in separate series, including when they select the same tasks. Record the actual protocol with the suite, source commit, model and agent versions, scoring reference and adopted attempt count. See the <a href="/TCSExam/docs/citation/#citing-results">reporting fields</a>.</p>`,16)])])}const u=t(i,[["render",r]]);export{k as __pageData,u as default};
